            <TextInput name="name" />
          </FormField>
          <FormField name="haveAlias">
            <CheckBox
              name="haveAlias"
              label="alias?"
              checked={haveAlias}
              onChange={() => setHaveAlias(!haveAlias)}
            />
          </FormField>
          {haveAlias && (
            <FormField label="Alias" name="alias" required>
              <TextInput name="alias" />
